     **/
    @IsNotEmpty()
    @Transform(({ value }) => parseFloat(value))
    @Min(-1000000000)
    @Max(1000000000)
    @IsNumber()
    @ApiProperty({ type: 'string', maximum: 1000000000, minimum: -1000000000 })
    public transactionAmount: string;
    /**
