async topUp({
    customer,
    currentBalance,
}: {
    customer: ReadCustomerResponseData;
    currentBalance?: number;
}): Promise<string | void> {
    if (this.billingCycle !== ValidBillingCycles.topUp || !this.topUpAmount) {
        return;
    }
    let balance = currentBalance;
    if (balance === undefined) {
        const { balance: foundBalance } = await this.invoicesService.creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer?.customerId || this.customerId,
        });
        balance = parseFloat(foundBalance);
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const topUpThreshold = parseFloat(this.topUpThreshold ?? '0.2');
    if (balance >= topUpThreshold * topUpAmount) {
        return;
    }
    const unitCost = Math.round((topUpAmount - balance) * 100) / 100;
    if (unitCost <= 0) {
        return;
    }
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, unitCost));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: customer?.customerId || this.customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

