private validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}) {
    const isTopUp = billingCycle === ValidBillingCycles.topUp;
    if (isTopUp && offeringType === OfferingType.subscription) {
        throw new BadRequestException('Subscription offerings cannot use topUp billing cycle');
    }
    if (isTopUp && !topUpAmount) {
        throw new BadRequestException('topUpAmount is required when billingCycle is topUp');
    }
    if (!isTopUp && (topUpAmount !== undefined || topUpThreshold !== undefined)) {
        throw new BadRequestException('topUpAmount and topUpThreshold are only valid when billingCycle is topUp');
    }
}

