private async storePaymentAsCreditIfNeeded(invoice, businessID: string, customerId: string) {
    if (!invoice?.storePaymentAsCredit) {
        return;
    }
    const creditAmount = invoice.totalAmountWithoutTax ?? invoice.total;
    if (!creditAmount || creditAmount <= 0) {
        return;
    }
    await this.creditService.create({
        customerId,
        businessID,
        transactionAmount: creditAmount.toFixed(2),
        metadata: {
            invoiceId: invoice.invoiceId,
            reason: `Top up credit from invoice ${invoice.invoiceId}`,
        },
        timestamp: new Date().toISOString(),
    });
}

